<?php
// Template generico GHZ para cardapio online em PHP + MySQL/cPanel.
// Copie para SITE-GHZ/api/{app}-menu-cloud.php e ajuste as constantes abaixo.
declare(strict_types=1);

header('Access-Control-Allow-Origin: *');
header('Access-Control-Allow-Methods: GET, POST, OPTIONS');
header('Access-Control-Allow-Headers: Content-Type, X-GHZ-Token');
if ($_SERVER['REQUEST_METHOD'] === 'OPTIONS') exit('ok');

const APP_ID = 'app';
const APP_NAME = 'Aplicativo';
const PUBLIC_BASE_PATH = 'app/cardapios';
const SQL_FILE = __DIR__ . '/../sql/app_menu_cloud_mysql.sql';

$configPath = __DIR__ . '/ml-config.php';
if (!file_exists($configPath)) respond(500, ['ok' => false, 'error' => 'missing_config']);
$config = require $configPath;
$action = strtolower(trim((string)($_GET['action'] ?? 'health')));

try {
    switch ($action) {
        case 'health':
            install_tables();
            respond(200, ['ok' => true, 'service' => APP_ID . '-menu-cloud', 'storage' => 'cpanel_mysql_files']);
        case 'publicar_cardapio':
            require_post(); install_tables(); respond(200, publicar_cardapio(request_json()));
        case 'publicar_garcom':
            require_post(); install_tables(); respond(200, publicar_garcom(request_json()));
        case 'numero':
            require_post(); install_tables(); respond(200, proximo_numero_publico(request_json()));
        case 'pedidos':
            require_post(); install_tables(); respond(200, pedidos(request_json()));
        default:
            respond(404, ['ok' => false, 'error' => 'not_found']);
    }
} catch (Throwable $e) {
    respond(500, ['ok' => false, 'error' => 'server_error', 'message' => 'Servidor de cardapio indisponivel no momento.']);
}

function config(string $key, mixed $default = null): mixed { global $config; return $config[$key] ?? $default; }
function respond(int $status, array $body): void { http_response_code($status); header('Content-Type: application/json; charset=utf-8'); header('Cache-Control: no-store'); echo json_encode($body, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE); exit; }
function require_post(): void { if ($_SERVER['REQUEST_METHOD'] !== 'POST') respond(405, ['ok' => false, 'error' => 'method_not_allowed']); }
function request_json(): array { $raw = file_get_contents('php://input') ?: ''; $data = json_decode($raw, true); return is_array($data) ? $data : []; }
function pdo(): PDO { static $pdo = null; if ($pdo instanceof PDO) return $pdo; $dsn = 'mysql:host=' . config('db_host', 'localhost') . ';dbname=' . config('db_name') . ';charset=utf8mb4'; $pdo = new PDO($dsn, (string)config('db_user'), (string)config('db_pass'), [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC, PDO::ATTR_EMULATE_PREPARES => false]); return $pdo; }
function install_tables(): void { $sql = file_get_contents(SQL_FILE); if ($sql === false) throw new RuntimeException('Arquivo SQL nao encontrado.'); foreach (array_filter(array_map('trim', explode(';', $sql))) as $statement) if ($statement !== '') pdo()->exec($statement); }
function base_url(): string { return 'https://ghzplugin.com.br'; }
function sha256_hex(string $value): string { return hash('sha256', $value); }
function clean_codigo(mixed $value): string { $text = strtolower((string)$value); $text = preg_replace('/[^a-z0-9-]/', '', $text) ?: ''; return substr($text, 0, 64); }
function clean_text(mixed $value, int $max = 120): string { $text = preg_replace('/\s+/', ' ', trim((string)$value)) ?: ''; return mb_substr($text, 0, $max, 'UTF-8'); }
function clean_pin(mixed $value): string { return substr(preg_replace('/\D+/', '', (string)$value) ?: '', 0, 4); }
function clean_origem(mixed $value): string { $origem = strtolower(clean_text($value, 20)); return in_array($origem, ['mesa','delivery','retirada','cardapio'], true) ? $origem : 'mesa'; }
function public_dir(string $codigo): string { return dirname(__DIR__) . '/' . PUBLIC_BASE_PATH . '/' . $codigo; }
function ensure_dir(string $dir): void { if (!is_dir($dir) && !mkdir($dir, 0755, true) && !is_dir($dir)) throw new RuntimeException('Nao foi possivel criar diretorio.'); }
function find_estabelecimento(string $codigo): ?array { $stmt = pdo()->prepare('select * from app_estabelecimentos where codigo = ? limit 1'); $stmt->execute([$codigo]); $row = $stmt->fetch(); return $row ?: null; }
function validate_publish_token(?array $est, string $token): void { if ($token === '' || strlen($token) < 32) respond(401, ['ok'=>false,'error'=>'invalid_token']); if ($est && !hash_equals((string)$est['token_hash'], sha256_hex($token))) respond(403, ['ok'=>false,'error'=>'invalid_publish_token']); if ($est && !(int)$est['ativo']) respond(403, ['ok'=>false,'error'=>'estabelecimento_inativo']); }
function upsert_estabelecimento(string $codigo, string $token, array $estabelecimento, array $hashes): int { $stmt = pdo()->prepare('insert into app_estabelecimentos (nome, telefone, endereco, documento, responsavel, pedido_token_hash, garcom_token_hash, codigo, token_hash, ultimo_publish_em) values (?, ?, ?, ?, ?, ?, ?, ?, ?, current_timestamp) on duplicate key update nome=values(nome), telefone=values(telefone), endereco=values(endereco), documento=values(documento), responsavel=values(responsavel), pedido_token_hash=coalesce(values(pedido_token_hash), pedido_token_hash), garcom_token_hash=coalesce(values(garcom_token_hash), garcom_token_hash), ultimo_publish_em=current_timestamp, ativo=1'); $stmt->execute([clean_text($estabelecimento['nome'] ?? APP_NAME, 120) ?: APP_NAME, clean_text($estabelecimento['telefone'] ?? '', 40) ?: null, clean_text($estabelecimento['endereco'] ?? '', 240) ?: null, clean_text($estabelecimento['documento'] ?? '', 40) ?: null, clean_text($estabelecimento['responsavel'] ?? '', 120) ?: null, $hashes['pedido'] ?? null, $hashes['garcom'] ?? null, $codigo, sha256_hex($token)]); $est = find_estabelecimento($codigo); return (int)$est['id']; }
function write_public_file(string $codigo, string $file, string $html): string { $dir = public_dir($codigo); ensure_dir($dir); if (file_put_contents($dir . '/' . $file, $html, LOCK_EX) === false) throw new RuntimeException('Nao foi possivel salvar HTML.'); return PUBLIC_BASE_PATH . '/' . $codigo . '/' . $file; }
function save_images(string $codigo, mixed $imagens): void { if (!is_array($imagens)) return; $dir = public_dir($codigo) . '/produtos'; ensure_dir($dir); foreach (array_slice($imagens, 0, 100) as $imagem) { if (!is_array($imagem)) continue; $produtoId = preg_replace('/[^a-zA-Z0-9_-]/', '', (string)($imagem['produto_id'] ?? '')) ?: ''; $produtoId = substr($produtoId, 0, 64); $dataUrl = (string)($imagem['data'] ?? ''); if ($produtoId === '' || !preg_match('/^data:image\/(webp|jpeg|png);base64,([a-zA-Z0-9+\/=]+)$/', $dataUrl, $m)) continue; $binary = base64_decode($m[2], true); if ($binary === false || strlen($binary) > 1048576) continue; file_put_contents($dir . '/' . $produtoId . '.webp', $binary, LOCK_EX); } }
function registrar_publicacao(int $estId, string $codigo, string $tipo, string $storagePath, string $html): void { $stmt = pdo()->prepare('insert into app_publicacoes_cardapio (estabelecimento_id, codigo, tipo, storage_path, html_bytes) values (?, ?, ?, ?, ?)'); $stmt->execute([$estId, $codigo, $tipo, $storagePath, strlen($html)]); }
function publicar_cardapio(array $body): array { $codigo = clean_codigo($body['codigo'] ?? ''); $token = (string)($body['token'] ?? ''); $pedidoToken = (string)($body['pedido_token'] ?? ''); $html = (string)($body['html'] ?? ''); if ($codigo === '' || strlen($codigo) < 6) respond(400, ['ok'=>false,'error'=>'invalid_codigo']); if ($pedidoToken === '' || strlen($pedidoToken) < 24) respond(401, ['ok'=>false,'error'=>'invalid_order_token']); if ($html === '' || strlen($html) < 100) respond(400, ['ok'=>false,'error'=>'invalid_html']); if (strlen($html) > 1000000) respond(413, ['ok'=>false,'error'=>'html_too_large']); $est = find_estabelecimento($codigo); validate_publish_token($est, $token); $estId = upsert_estabelecimento($codigo, $token, is_array($body['estabelecimento'] ?? null) ? $body['estabelecimento'] : [], ['pedido'=>sha256_hex($pedidoToken)]); save_images($codigo, $body['imagens'] ?? []); $path = write_public_file($codigo, 'index.html', $html); registrar_publicacao($estId, $codigo, 'cardapio', $path, $html); $url = base_url() . '/' . $path; return ['ok'=>true,'codigo'=>$codigo,'storagePath'=>$path,'publicUrl'=>$url]; }
function publicar_garcom(array $body): array { $codigo = clean_codigo($body['codigo'] ?? ''); $token = (string)($body['token'] ?? ''); $garcomToken = (string)($body['garcom_token'] ?? ''); $html = (string)($body['html'] ?? ''); if ($codigo === '' || strlen($codigo) < 6) respond(400, ['ok'=>false,'error'=>'invalid_codigo']); if ($garcomToken === '' || strlen($garcomToken) < 24) respond(401, ['ok'=>false,'error'=>'invalid_waiter_token']); if ($html === '' || strlen($html) < 100) respond(400, ['ok'=>false,'error'=>'invalid_html']); if (strlen($html) > 1000000) respond(413, ['ok'=>false,'error'=>'html_too_large']); $est = find_estabelecimento($codigo); validate_publish_token($est, $token); $estId = upsert_estabelecimento($codigo, $token, is_array($body['estabelecimento'] ?? null) ? $body['estabelecimento'] : [], ['garcom'=>sha256_hex($garcomToken)]); pdo()->prepare('update app_garcons_online set ativo = 0 where estabelecimento_id = ?')->execute([$estId]); $stmt = pdo()->prepare('insert into app_garcons_online (estabelecimento_id, garcom_id, codigo, nome, pin_hash, ativo) values (?, ?, ?, ?, ?, 1) on duplicate key update codigo=values(codigo), nome=values(nome), pin_hash=values(pin_hash), ativo=1'); foreach (array_slice(is_array($body['garcons'] ?? null) ? $body['garcons'] : [], 0, 100) as $garcom) { if (!is_array($garcom)) continue; $id = clean_text($garcom['id'] ?? '', 64); $nome = clean_text($garcom['nome'] ?? '', 120); $pin = clean_pin($garcom['pin'] ?? ''); if ($id === '' || $nome === '' || strlen($pin) !== 4) continue; $stmt->execute([$estId, $id, clean_text($garcom['codigo'] ?? '', 20) ?: null, $nome, sha256_hex($pin)]); } $path = write_public_file($codigo, 'garcom.html', $html); registrar_publicacao($estId, $codigo, 'garcom', $path, $html); return ['ok'=>true,'codigo'=>$codigo,'publicUrl'=>base_url().'/'.$path]; }
function next_number(int $estId): int { pdo()->beginTransaction(); try { $stmt = pdo()->prepare('select next_order_number from app_estabelecimentos where id = ? for update'); $stmt->execute([$estId]); $n = max(1, (int)($stmt->fetch()['next_order_number'] ?? 1)); pdo()->prepare('update app_estabelecimentos set next_order_number = ? where id = ?')->execute([$n + 1, $estId]); pdo()->commit(); return $n; } catch (Throwable $e) { pdo()->rollBack(); throw $e; } }
function proximo_numero_publico(array $body): array { $codigo = clean_codigo($body['codigo'] ?? ''); $pedidoToken = (string)($body['pedido_token'] ?? ''); $est = find_estabelecimento($codigo); if (!$est || !(int)$est['ativo']) respond(403, ['ok'=>false,'error'=>'estabelecimento_invalido']); if ($pedidoToken === '' || empty($est['pedido_token_hash']) || !hash_equals((string)$est['pedido_token_hash'], sha256_hex($pedidoToken))) respond(403, ['ok'=>false,'error'=>'unauthorized_menu']); return ['ok'=>true,'numero'=>next_number((int)$est['id'])]; }
function normalize_items(mixed $items): array { $out = []; foreach (array_slice(is_array($items) ? $items : [], 0, 80) as $item) { if (!is_array($item)) continue; $nome = clean_text($item['nome'] ?? '', 120); $qtd = max(1, min(99, (float)($item['qtd'] ?? 1))); if ($nome === '') continue; $out[] = ['produto_id'=>clean_text($item['produto_id'] ?? '', 64), 'nome'=>$nome, 'preco'=>(float)($item['preco'] ?? 0), 'qtd'=>$qtd, 'obs'=>clean_text($item['obs'] ?? '', 240), 'setor_preparo'=>clean_text($item['setor_preparo'] ?? '', 30)]; } return $out; }
function total_items(array $items): float { return array_reduce($items, fn($sum, $item) => $sum + ((float)$item['preco'] * (float)$item['qtd']), 0.0); }
function pedidos(array $body): array { $action = strtolower(clean_text($body['action'] ?? 'criar', 30)); $codigo = clean_codigo($body['codigo'] ?? ''); $est = find_estabelecimento($codigo); if (!$est || !(int)$est['ativo']) respond(403, ['ok'=>false,'error'=>'estabelecimento_invalido']); if ($action === 'criar_cardapio') return criar_pedido_cardapio($est, $body); if ($action === 'criar') return criar_pedido_mesa($est, $body); $token = (string)($body['token'] ?? ''); if ($token === '' || !hash_equals((string)$est['token_hash'], sha256_hex($token))) respond(403, ['ok'=>false,'error'=>'unauthorized_admin']); if ($action === 'listar') return listar_pedidos($est, $body); if (in_array($action, ['importar','atender','recusar'], true)) return atualizar_pedido($est, $body, $action); respond(400, ['ok'=>false,'error'=>'unknown_action']); }
function criar_pedido_cardapio(array $est, array $body): array { $pedidoToken = (string)($body['pedido_token'] ?? ''); if ($pedidoToken === '' || empty($est['pedido_token_hash']) || !hash_equals((string)$est['pedido_token_hash'], sha256_hex($pedidoToken))) respond(403, ['ok'=>false,'error'=>'unauthorized_order']); $items = normalize_items($body['itens'] ?? []); if (!$items) respond(400, ['ok'=>false,'error'=>'empty_order']); $numero = (int)($body['numero'] ?? 0); if ($numero <= 0) $numero = next_number((int)$est['id']); $origem = clean_origem($body['origem'] ?? 'delivery'); $payload = ['itens'=>$items, 'total'=>total_items($items), 'origem'=>$origem, 'forma_pagamento'=>clean_text($body['forma_pagamento'] ?? '', 60), 'tipo_entrega'=>clean_text($body['tipo_entrega'] ?? '', 80), 'troco'=>clean_text($body['troco'] ?? '', 40)]; return ['ok'=>true,'pedido'=>insert_order($est, $numero, $origem, $payload, ['cliente_nome'=>clean_text($body['cliente_nome'] ?? '', 120), 'telefone'=>clean_text($body['telefone'] ?? '', 40), 'endereco'=>clean_text($body['endereco'] ?? '', 240), 'forma_pagamento'=>$payload['forma_pagamento'], 'tipo_entrega'=>$payload['tipo_entrega'], 'observacao'=>clean_text($body['observacao'] ?? '', 300)])]; }
function criar_pedido_mesa(array $est, array $body): array { $garcomToken = (string)($body['garcom_token'] ?? ''); if ($garcomToken === '' || empty($est['garcom_token_hash']) || !hash_equals((string)$est['garcom_token_hash'], sha256_hex($garcomToken))) respond(403, ['ok'=>false,'error'=>'unauthorized_waiter']); $items = normalize_items($body['itens'] ?? []); if (!$items) respond(400, ['ok'=>false,'error'=>'empty_order']); $numero = next_number((int)$est['id']); return ['ok'=>true,'pedido'=>insert_order($est, $numero, 'mesa', ['itens'=>$items,'total'=>total_items($items),'origem'=>'mesa'], ['mesa_id'=>clean_text($body['mesa_id'] ?? '', 64), 'mesa_num'=>clean_text($body['mesa_num'] ?? '', 40), 'garcom_id'=>clean_text($body['garcom_id'] ?? '', 64), 'garcom_nome'=>clean_text($body['garcom_nome'] ?? '', 120), 'cliente_nome'=>clean_text($body['cliente_nome'] ?? '', 120), 'observacao'=>clean_text($body['observacao'] ?? '', 300)])]; }
function insert_order(array $est, int $numero, string $origem, array $payload, array $extra): array { $id = bin2hex(random_bytes(16)); $stmt = pdo()->prepare('insert into app_pedidos_online (id, estabelecimento_id, codigo, numero, origem, mesa_id, mesa_num, garcom_id, garcom_codigo, garcom_nome, cliente_nome, telefone, endereco, forma_pagamento, tipo_entrega, observacao, payload) values (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'); $stmt->execute([$id, (int)$est['id'], $est['codigo'], $numero, $origem, $extra['mesa_id'] ?? null, $extra['mesa_num'] ?? null, $extra['garcom_id'] ?? null, $extra['garcom_codigo'] ?? null, $extra['garcom_nome'] ?? null, $extra['cliente_nome'] ?? null, $extra['telefone'] ?? null, $extra['endereco'] ?? null, $extra['forma_pagamento'] ?? null, $extra['tipo_entrega'] ?? null, $extra['observacao'] ?? null, json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE)]); return ['id'=>$id,'numero'=>$numero]; }
function listar_pedidos(array $est, array $body): array { $origens = []; if (is_array($body['origens'] ?? null)) foreach ($body['origens'] as $origem) { $o = clean_origem($origem); if (!in_array($o, $origens, true)) $origens[] = $o; } $sql = 'select id, numero, origem, mesa_id, mesa_num, garcom_id, garcom_codigo, garcom_nome, cliente_nome, telefone, endereco, forma_pagamento, tipo_entrega, observacao, status, payload, criado_em from app_pedidos_online where estabelecimento_id = ? and status = "pendente"'; $params = [(int)$est['id']]; if ($origens) { $sql .= ' and origem in (' . implode(',', array_fill(0, count($origens), '?')) . ')'; $params = array_merge($params, $origens); } $sql .= ' order by criado_em asc limit 80'; $stmt = pdo()->prepare($sql); $stmt->execute($params); $rows = $stmt->fetchAll() ?: []; foreach ($rows as &$row) $row['payload'] = json_decode((string)$row['payload'], true) ?: []; return ['ok'=>true,'pedidos'=>$rows]; }
function atualizar_pedido(array $est, array $body, string $action): array { $pedidoId = clean_text($body['pedido_id'] ?? '', 80); if ($pedidoId === '') respond(400, ['ok'=>false,'error'=>'invalid_order']); $recusando = $action === 'recusar'; $stmt = pdo()->prepare('update app_pedidos_online set status = ?, atendimento_local_id = ?, importado_em = current_timestamp where id = ? and estabelecimento_id = ? and status = "pendente"'); $stmt->execute([$recusando ? 'cancelado' : 'importado', $recusando ? clean_text($body['motivo'] ?? 'recusado', 40) : clean_text($body['atendimento_id'] ?? '', 80), $pedidoId, (int)$est['id']]); return ['ok'=>true]; }
